    // 1. 初始化输出默认值 (Fault defaults)
    sd_output.mode = SD_FAULT;
    sd_output.accepted = FALSE32;
    sd_output.rejects = 0U;
    sd_output.cosine = 0.0;
    sd_output.innovation_rad = 0.0;
    sd_output.reference.x = 0.0;
    sd_output.reference.y = 0.0;
    sd_output.reference.z = 0.0;

    // 2. 处理 Disable: 清除引用和计数器，进入 OFF 模式
    if (sd_input.enable == 0) {
        sd_state.mode = SD_OFF;
        sd_state.initialized = 0;
        sd_state.rejects = 0U;
        sd_state.reacquire_count = 0U;
        sd_state.reference.x = 0.0;
        sd_state.reference.y = 0.0;
        sd_state.reference.z = 0.0;

        sd_output.mode = SD_OFF;
        return;
    }

    // 3. 参数有效性检查 (Validation)
    // 检查指针
    if (sd_input.sun_body == NULL) {
        goto fault_latch;
    }

    // 检查向量有限性
    if (!adcs_is_finite_vec3(sd_input.sun_body)) {
        goto fault_latch;
    }

    // 检查配置参数范围
    double alpha = sd_config.alpha;
    double min_cos = sd_config.minimum_cosine;
    double reacq_min_cos = sd_config.reacquire_min_cosine;
    unint32 max_rej = sd_config.max_rejects;
    unint32 reacq_conf = sd_config.reacquire_confirm;

    if (!isfinite(alpha) || alpha <= 0.0 || alpha > 1.0) goto fault_latch;
    if (!isfinite(min_cos) || min_cos < -1.0 || min_cos > 1.0) goto fault_latch;
    if (!isfinite(reacq_min_cos) || reacq_min_cos < -1.0 || reacq_min_cos > 1.0) goto fault_latch;
    if (max_rej < 1 || max_rej > 20) goto fault_latch;
    if (reacq_conf < 1 || reacq_conf > 20) goto fault_latch;

    // 4. 归一化输入向量
    adcs_vec3_t normalized_sample;
    adcs_status_t norm_status = adcs_vec3_normalize(sd_input.sun_body, ADCS_EPS_NORM, &normalized_sample);
    if (norm_status != ADCS_OK) {
        goto fault_latch;
    }

    // 5. 状态机主逻辑
    switch (sd_state.mode) {
        case SD_TRACK:
        case SD_REJECT: {
            // 计算余弦值
            double cosine = adcs_vec3_dot(&normalized_sample, &sd_state.reference);
            // 限制余弦值在 [-1, 1] 以防浮点误差导致 acos 域错误
            if (cosine > 1.0) cosine = 1.0;
            if (cosine < -1.0) cosine = -1.0;

            double innovation = acos(cosine);

            if (cosine >= min_cos) {
                // Accept: Blend reference
                double one_minus_alpha = 1.0 - alpha;
                sd_state.reference = adcs_vec3_add(
                    &adcs_vec3_scale(&sd_state.reference, one_minus_alpha),
                    &adcs_vec3_scale(&normalized_sample, alpha)
                );
                // Re-normalize reference to ensure it stays unit length
                adcs_vec3_normalize(&sd_state.reference, ADCS_EPS_NORM, &sd_state.reference);

                sd_state.rejects = 0U;
                sd_state.mode = SD_TRACK;

                sd_output.mode = SD_TRACK;
                sd_output.accepted = TRUE32;
                sd_output.cosine = cosine;
                sd_output.innovation_rad = innovation;
                sd_output.reference = sd_state.reference;
                return;
            } else {
                // Reject
                sd_state.rejects++;
                if (sd_state.rejects >= max_rej) {
                    sd_state.mode = SD_LOST;
                } else {
                    sd_state.mode = SD_REJECT;
                }
                // Reference preserved

                sd_output.mode = sd_state.mode;
                sd_output.accepted = FALSE32;
                sd_output.cosine = cosine;
                sd_output.innovation_rad = innovation;
                sd_output.rejects = sd_state.rejects;
                sd_output.reference = sd_state.reference;
                return;
            }
        }

        case SD_LOST: {
            double cosine = adcs_vec3_dot(&normalized_sample, &sd_state.reference);
            if (cosine > 1.0) cosine = 1.0;
            if (cosine < -1.0) cosine = -1.0;
            double innovation = acos(cosine);

            if (cosine >= reacq_min_cos) {
                sd_state.reacquire_count++;
                if (sd_state.reacquire_count >= reacq_conf) {
                    // Re-acquired: Blend as ordinary accept
                    double one_minus_alpha = 1.0 - alpha;
                    sd_state.reference = adcs_vec3_add(
                        &adcs_vec3_scale(&sd_state.reference, one_minus_alpha),
                        &adcs_vec3_scale(&normalized_sample, alpha)
                    );
                    adcs_vec3_normalize(&sd_state.reference, ADCS_EPS_NORM, &sd_state.reference);

                    sd_state.rejects = 0U;
                    sd_state.reacquire_count = 0U;
                    sd_state.mode = SD_TRACK;

                    sd_output.mode = SD_TRACK;
                    sd_output.accepted = TRUE32;
                    sd_output.cosine = cosine;
                    sd_output.innovation_rad = innovation;
                    sd_output.reference = sd_state.reference;
                    return;
                } else {
                    // Still LOST, incrementing count
                    sd_output.mode = SD_LOST;
                    sd_output.accepted = FALSE32;
                    sd_output.cosine = cosine;
                    sd_output.innovation_rad = innovation;
                    sd_output.rejects = sd_state.rejects;
                    sd_output.reference = sd_state.reference;
                    return;
                }
            } else {
                // Cosine too low, reset reacquire count
                sd_state.reacquire_count = 0U;
                sd_output.mode = SD_LOST;
                sd_output.accepted = FALSE32;
                sd_output.cosine = cosine;
                sd_output.innovation_rad = innovation;
                sd_output.rejects = sd_state.rejects;
                sd_output.reference = sd_state.reference;
                return;
            }
        }

        case SD_FAULT: {
            // Fault latches until disable
            sd_output.mode = SD_FAULT;
            sd_output.accepted = FALSE32;
            sd_output.cosine = 0.0;
            sd_output.innovation_rad = 0.0;
            sd_output.reference.x = 0.0;
            sd_output.reference.y = 0.0;
            sd_output.reference.z = 0.0;
            return;
        }

        default: {
            // Initial state or OFF (though OFF is handled by enable check, handle uninitialized TRACK entry)
            // If mode is not set or uninitialized, we treat first valid sample as initialization
            sd_state.mode = SD_TRACK;
            sd_state.initialized = 1;
            sd_state.rejects = 0U;
            sd_state.reacquire_count = 0U;
            sd_state.reference = normalized_sample;

            sd_output.mode = SD_TRACK;
            sd_output.accepted = TRUE32;
            sd_output.cosine = 1.0;
            sd_output.innovation_rad = 0.0;
            sd_output.reference = sd_state.reference;
            return;
        }
    }

fault_latch:
    sd_state.mode = SD_FAULT;
    // Output remains defaults (Fault values)
    return;

